  /// The RFC 7616 section 3.9.1 example: its nonce, opaque and client nonce.
  private static let digestNonce = "7ypf/xlj9XXwfDPEoM4URrv/xwf94BcCAzFZH4GiTo0v"
  private static let digestOpaque = "FQhe/qaU925kfnzjCev0ciny7QMkPqMAFRtzCUYo5tdS"
  private static let digestCnonce = "f2/wE4q74E6zIJEtWaHKaf5wv/H5QzzpXusqGemxURZJ"

  /// The RFC 7616 example user's DigestAuthenticator with the example's client nonce.
  private func digestAuthenticator() throws -> DigestAuthenticator {
    let auth = try DigestAuthenticator(
      host: "https://api.example.com", username: "Mufasa", password: "Circle of Life")
    auth.fixCnonce(Self.digestCnonce)
    return auth
  }

  /// Feeds a challenge and returns the answer for GET /dir/index.html.
  private func digestAnswer(_ challenge: String) throws -> String? {
    let auth = try digestAuthenticator()
    #expect(auth.acceptChallenge(challenge))
    return auth.authorization(method: "GET", requestTarget: "/dir/index.html")
  }

  /* The MD5 answer to the RFC 7616 example challenge has the published
   * response and the header fields in the fixed order. */
  @Test func testBhvAuthdigest700TheMd5AnswerToTheRfc7616ExampleIsThePublishedOne() throws {
    let got = try digestAnswer(
      "Digest realm=\"http-auth@example.org\", qop=\"auth, auth-int\", algorithm=MD5, "
        + "nonce=\"\(Self.digestNonce)\", opaque=\"\(Self.digestOpaque)\"")
    #expect(
      got
        == "Digest username=\"Mufasa\", realm=\"http-auth@example.org\", nonce=\"\(Self.digestNonce)\", "
        + "uri=\"/dir/index.html\", algorithm=MD5, response=\"8ca523f5e9506fed4657c9700eebdbec\", "
        + "qop=auth, nc=00000001, cnonce=\"\(Self.digestCnonce)\", opaque=\"\(Self.digestOpaque)\"")
  }

