        + "Digest realm=\"http-auth@example.org\", algorithm=MD5, nonce=\"other\"")
    #expect(
      got
        == "Digest username=\"Mufasa\", realm=\"http-auth@example.org\", nonce=\"\(Self.digestNonce)\", "
        + "uri=\"/dir/index.html\", algorithm=\(algorithm), response=\"\(response)\", "
        + "qop=auth, nc=00000001, cnonce=\"\(Self.digestCnonce)\", opaque=\"\(Self.digestOpaque)\"")
  }

  /* A challenge without qop is answered in the RFC 2069 form, with no qop, nc
   * or cnonce; opaque is echoed only when sent and algorithm only when named, as written. */
  @Test func testBhvAuthdigest704AChallengeWithoutQopIsAnsweredInTheRfc2069Form() throws {
    let plain = try digestAnswer(
      "Digest realm=\"http-auth@example.org\", nonce=\"\(Self.digestNonce)\"")
    #expect(
      plain
        == "Digest username=\"Mufasa\", realm=\"http-auth@example.org\", nonce=\"\(Self.digestNonce)\", "
        + "uri=\"/dir/index.html\", response=\"7b2cc3b30e75b4777ea31027084363fd\"")
    let named = try digestAnswer(
      "digest realm=\"http-auth@example.org\", nonce=\"\(Self.digestNonce)\", algorithm=md5, "
        + "opaque=\"\(Self.digestOpaque)\"")
    #expect(
      named
        == "Digest username=\"Mufasa\", realm=\"http-auth@example.org\", nonce=\"\(Self.digestNonce)\", "
        + "uri=\"/dir/index.html\", algorithm=md5, response=\"7b2cc3b30e75b4777ea31027084363fd\", "
        + "opaque=\"\(Self.digestOpaque)\"")
  }

